UPDATE public.products AS product
SET
  name = catalog.name,
  slug = catalog.slug,
  description = 'The ' || catalog.name || ' is listed in CartScout''s golf cart collection. Contact our team to confirm its condition, specifications, included equipment, current availability, final rand price, and delivery arrangements for your location.',
  seo_title = catalog.name,
  seo_description = 'Explore this CartScout listing. Enquire to confirm specifications, current availability, final rand price, and delivery arrangements.',
  image_url = '/images/carts/' || catalog.slug || '.webp',
  source_url = NULL,
  source_price = NULL,
  source_currency = NULL,
  exchange_rate_zar_per_unit = NULL,
  exchange_rate_as_of = NULL,
  image_gallery = '[]'::jsonb,
  updated_at = now()
FROM catalog
WHERE product.source_product_id = catalog.source_product_id;
